<script lang="ts">
 import {onDestroy} from 'svelte';import {invalidateAll} from '$app/navigation';import {saveDraft} from '$lib/offline';
 let {model,t,lang,tenantId}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;lang:string;tenantId:string}=$props();let text=$state(''),taskTitle=$state(''),query=$state(''),searchResults=$state<any[]>([]),proposal=$state<any>(null),busy=$state(false),message=$state(''),lot=$state(''),parameter=$state('temperature'),value=$state(''),unit=$state(''),method=$state(''),date=$state(''),sample=$state(''),listening=$state(false),speech:any=null,confirmed=$state(false),speechConsent=$state(false);
 let connection=$derived(model.connections.find(c=>c.adapter==='openai-compatible'&&c.enabled));
 async function semantic(action:string){if(!connection)return;busy=true;try{const res=await fetch('/api/search/semantic',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,connection_id:connection.id,query:query||undefined,request_id:crypto.randomUUID()})});const r=await res.json();if(res.ok){if(action==='search')searchResults=r.results;else message=t('indexed')+' '+r.indexed+' · '+t('remaining')+' '+r.remaining;}else message=t(r.message);}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
 async function find(){busy=true;try{const res=await fetch('/api/search?q='+encodeURIComponent(query));const result=await res.json();if(res.ok)searchResults=result.results;else message=t(result.message);}finally{busy=false;}}
 async function ai(){if(!connection)return;busy=true;message='';try{const res=await fetch('/api/assistant',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({connection_id:connection.id,text,query:query||undefined,request_id:crypto.randomUUID()})});proposal=await res.json();if(!res.ok){message=t(proposal.message);proposal=null;return;}if(proposal.draft?.kind==='task')taskTitle=proposal.draft.body.slice(0,160);if(proposal.draft?.kind==='analysis'){parameter=proposal.draft.parameter??'temperature';value=proposal.draft.value??'';unit=proposal.draft.unit??'';}}catch{message=t('connectionError');}finally{busy=false;}}
 function speak(){const Speech=(window as any).SpeechRecognition??(window as any).webkitSpeechRecognition;if(!Speech){message=t('speechUnavailable');return;}if(listening){speech.stop();return;}speech=new Speech();speech.lang=({de:'de-DE',en:'en-GB',it:'it-IT',fr:'fr-FR'} as Record<string,string>)[lang];speech.continuous=true;speech.interimResults=false;speech.onresult=(event:any)=>{for(let i=event.resultIndex;i<event.results.length;i++)if(event.results[i].isFinal)text+=(text?' ':'')+event.results[i][0].transcript;};speech.onerror=()=>{message=t('speechUnavailable');listening=false;};speech.onend=()=>listening=false;listening=true;speech.start();}
 async function ocr(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file||file.size>2097152){message=t('FILE_TOO_LARGE');return;}busy=true;message=t('ocrLoading');let worker:any,pdf:any,pdfTask:any;try{
  async function recognize(image:any){if(!worker){const {createWorker}=await import('tesseract.js');worker=await createWorker(({de:'deu',en:'eng',it:'ita',fr:'fra'} as Record<string,string>)[lang],1,{workerPath:'/ocr/worker.min.js',corePath:'/ocr/core',langPath:'/ocr/lang',gzip:false,logger:()=>{}});}return worker.recognize(image);}
  if(file.type==='application/pdf'){const library=await import('pdfjs-dist');library.GlobalWorkerOptions.workerSrc='/ocr/pdf.worker.min.mjs';pdfTask=library.getDocument({data:new Uint8Array(await file.arrayBuffer()),wasmUrl:'/ocr/wasm/',standardFontDataUrl:'/ocr/standard_fonts/',disableFontFace:true});pdf=await pdfTask.promise;if(pdf.numPages>10)throw new Error('PDF_PAGE_LIMIT');let extracted='';for(let n=1;n<=pdf.numPages&&extracted.length<5000;n++){const page=await pdf.getPage(n),content=await page.getTextContent();let part=content.items.map((i:any)=>i.str??'').join(' ');if(part.trim().length<20){if(n>3)throw new Error('PDF_SCAN_LIMIT');const viewport=page.getViewport({scale:1.5});if(viewport.width*viewport.height>6000000)throw new Error('PDF_PAGE_TOO_LARGE');const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvas,viewport}).promise;part=(await recognize(canvas)).data.text;}extracted+=part+'\n';page.cleanup();}text=extracted.slice(0,5000);message=t('ocrReview');
  }else{const r=await recognize(file);text=r.data.text.slice(0,5000);message=t('ocrReview')+' '+Math.round(r.data.confidence)+'%';}
 }catch{message=t('OCR_FAILED');}finally{try{await worker?.terminate();}finally{try{await pdfTask?.destroy();}finally{busy=false;}}}}

 async function save(kind:'note'|'analysis'|'task'){if(!confirmed)return;const command:Record<string,any>=kind==='task'?{type:'task_create',title:taskTitle,description:text,...(lot?{lot_id:lot}:{})}:kind==='note'?{type:'note_add',body:text,...(lot?{lot_id:lot}:{})}:{type:'analysis_add',lot_id:lot,sample_code:sample,sampled_at:new Date(date).toISOString(),parameter,value,unit,method,measured_at:new Date(date).toISOString(),quality:'measured'};busy=true;try{if(!navigator.onLine){await saveDraft(tenantId,command);message=t('draftSaved');return;}const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify(command)});message=res.ok?t('saved'):t((await res.json()).message);if(res.ok){confirmed=false;await invalidateAll();}}finally{busy=false;}}
 onDestroy(()=>speech?.stop());
</script>
<section class="card"><h2>{t('searchData')}</h2><form onsubmit={(e)=>{e.preventDefault();find();}}><label>{t('query')}<input bind:value={query} required minlength="2" maxlength="160" /></label><button disabled={busy}>{t('search')}</button></form>{#if connection?.configuration?.embedding_model}<div class="actions"><button onclick={()=>semantic('index')} disabled={busy}>{t('indexSearch')}</button><button onclick={()=>semantic('search')} disabled={busy||query.length<2}>{t('semanticSearch')}</button></div>{/if}{#each searchResults as row}<details><summary>{t(row.collection)} · {row.record_id.slice(0,8)}</summary><pre>{row.body}</pre></details>{/each}</section>
<section class="card"><h2>{t('captureNote')}</h2><label>{t('body')}<textarea bind:value={text} maxlength="5000" rows="6"></textarea></label><label class="check"><input type="checkbox" bind:checked={speechConsent} />{t('speechConsent')}</label><div class="actions"><button onclick={speak} disabled={busy||!speechConsent}>{t(listening?'stopSpeech':'startSpeech')} · {lang.toUpperCase()}</button>{#if connection}<button onclick={ai} disabled={busy||!text}>{t('structureWithAI')}</button>{/if}</div><p class="muted">{t('ocrHint')}</p><label>OCR<input type="file" accept="image/png,image/jpeg,application/pdf" onchange={ocr} disabled={busy} /></label>{#if !connection}<p class="muted">{t('aiNotConnected')}</p>{/if}{#if proposal}<article><h3>{t('draft')}</h3><p>{proposal.summary}</p><ul>{#each proposal.citations??[] as id}<li>{id}</li>{/each}{#each proposal.uncertainties??[] as item}<li>{item}</li>{/each}</ul></article>{/if}<label>{t('lot_id')}<select bind:value={lot}><option value="">—</option>{#each model.lots as l}<option value={l.id}>{l.code} · {l.name}</option>{/each}</select></label><label class="check"><input type="checkbox" bind:checked={confirmed} />{t('confirmCapture')}</label><button onclick={()=>save('note')} disabled={!confirmed||busy||!text}>{t('note_add')}</button><details><summary>{t('task_create')}</summary><label>{t('title')}<input bind:value={taskTitle} maxlength="160" /></label><button onclick={()=>save('task')} disabled={!confirmed||busy||!taskTitle}>{t('task_create')}</button></details><details><summary>{t('analysis_add')}</summary><div class="grid"><label>{t('parameter')}<select bind:value={parameter}>{#each ['temperature','alcohol','sugar','acidity','ph','free_so2'] as p}<option value={p}>{p==='ph'?'pH':t(p)}</option>{/each}</select></label><label>{t('value')}<input bind:value={value} /></label><label>{t('unit')}<input bind:value={unit} /></label><label>{t('method')}<input bind:value={method} /></label><label>{t('sample_code')}<input bind:value={sample} /></label><label>{t('measured_at')}<input type="datetime-local" bind:value={date} /></label></div><button onclick={()=>save('analysis')} disabled={!confirmed||busy||!lot||!date||!sample||!value||!unit||!method}>{t('analysis_add')}</button></details><p role="status">{message}</p></section>
<style>.actions{display:flex;gap:10px;margin:15px 0;flex-wrap:wrap}.check{display:flex;align-items:center;margin:16px 0}.check input{width:18px;height:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}button{margin:10px 0}article{background:#f4f7f0;padding:15px;margin:20px 0}</style>
